// src/lib/api/users.ts
var UserAPI = class {
	userId;
	constructor(userId) {
		this.userId = userId;
	}
	_makeRequest = async (method, path = "", body) => {
		const options = {
			method,
			headers: {
				"content-type": "application/json",
				accept: "application/json"
			}
		};
		if (body) options.body = JSON.stringify(body);
		return await fetch(`/pdc/users/${this.userId}${path}`, options);
	};
	setActiveGroup = async (groupId) => {
		return await this._makeRequest("PATCH", `/groups/${groupId}`, { active: true }).then((resp) => resp.json()).then(({ membership }) => membership);
	};
	delete = async () => {
		return await this._makeRequest("DELETE");
	};
};
var UsersAPI = class {
	_makeRequest = async (method, query = "") => {
		const options = {
			method,
			headers: { accept: "application/json" }
		};
		return await fetch(`/pdc/users?${query}`, options);
	};
	all = async () => {
		return await this._makeRequest("GET");
	};
	search = async (search, options) => {
		const params = new URLSearchParams();
		params.append("name", search);
		if (options?.groupId) params.append("groupId", options.groupId);
		if (options?.excludedUserIds) params.append("excludedUserIds", options.excludedUserIds.join(","));
		return await this._makeRequest("GET", params.toString());
	};
};
var InviteUsersAPI = class {
	_makeRequest = async (method, body) => {
		const options = {
			method,
			headers: { accept: "application/json" },
			body: JSON.stringify(body)
		};
		return await fetch("/pdc/users/invite", options);
	};
	invite = async (data) => {
		return await this._makeRequest("POST", data);
	};
};
var SystemUsersAPI = class {
	groupId;
	constructor(groupId) {
		this.groupId = groupId;
	}
	_makeRequest = async (method, body) => {
		const options = {
			method,
			headers: {
				"content-type": "application/json",
				accept: "application/json"
			},
			body: JSON.stringify(body)
		};
		return await fetch(`/pdc/users/public`, options);
	};
	create = async (username, name) => {
		return await this._makeRequest("POST", {
			username,
			name,
			groupId: this.groupId
		});
	};
};
export { UsersAPI as i, SystemUsersAPI as n, UserAPI as r, InviteUsersAPI as t };
